+export function generateBeats(bpm, durationMs, subdivision = 1, seed = Date.now(), level = 'normal') {
+  const safeBpm = clamp(bpm, 30, 300);
+  const sub = SUBDIVISIONS.includes(subdivision) ? subdivision : 1;
+  const groove = DIFFICULTY[level]?.groove ?? DIFFICULTY.normal.groove;
+  const baseInterval = 60000 / safeBpm / sub;
+  const rng = createRng(seed);
+  const beats = [];
+  let t = 0;
+  // 每 4 拍选一个微变速方向（±groove），用线性插值产生平滑摆动。
+  let segStart = 0;
+  let segRatio = 1;
+  let nextRatio = 1 + randomBetween(rng, -groove, groove);
+  let segCount = 0;
+  while (t <= durationMs + baseInterval) {
+    beats.push({ time: t, interval: baseInterval });
+    if (segCount % 4 === 0) {
+      segStart = t;
+      segRatio = nextRatio;
+      nextRatio = 1 + randomBetween(rng, -groove, groove);
+    }
+    const phase = (t - segStart) / (baseInterval * 4);
+    const ratio = segRatio + (nextRatio - segRatio) * clamp(phase, 0, 1);
+    t += baseInterval * ratio;
+    segCount += 1;
+  }
+  return beats;
+}
