    seed = Date.now(),
    area = { width: 900, height: 520 }
  } = opts;
  const cfg = DIFFICULTY[difficulty] ?? DIFFICULTY.normal;
  const rng = createRng(seed);
  const targets = [];
  let t = 1500;
  let index = 0;
  const phases = [
    { end: durationMs / 3, gapMul: 1.35, noGoRate: 0.08 },
    { end: (durationMs / 3) * 2, gapMul: 1.0, noGoRate: 0.14 },
    { end: durationMs, gapMul: 0.7, noGoRate: 0.2 }
  ];
  while (t < durationMs - cfg.lifetimeMs) {
    const phase = phases.find((p) => t < p.end) ?? phases[phases.length - 1];
    const size = Math.round(randomBetween(rng, cfg.targetMin, cfg.targetMax));
    const padding = 12;
    const x = Math.round(randomBetween(rng, padding, Math.max(padding + 1, area.width - size - padding)));
    const y = Math.round(randomBetween(rng, padding, Math.max(padding + 1, area.height - size - padding)));
    const isNoGo = rng() < phase.noGoRate;
    targets.push({
      id: index,
      appearTime: Math.round(t),
      lifetimeMs: cfg.lifetimeMs,
      x,
      y,
      size,
      color: isNoGo ? '#c9ced6' : randomPick(rng, TARGET_COLORS),
      shape: randomPick(rng, ['circle', 'square']),
      noGo: isNoGo,
      phase: phases.indexOf(phase)
    });
    const gap =
      randomBetween(rng, cfg.gapMin, cfg.gapMax) * phase.gapMul + cfg.lifetimeMs * 0.2;
    t += gap;
    index += 1;
  }
  return targets;
}

/** 判断点击坐标是否落在目标矩形内。 */
export function isPointInTarget(x, y, target) {
  return (
    x >= target.x &&
    x <= target.x + target.size &&
    y >= target.y &&
    y <= target.y + target.size
  );
}

/** 圆形目标使用圆形命中区。 */
export function isHitAtPoint(x, y, target) {
  if (target.shape === 'circle') {
    const cx = target.x + target.size / 2;
    const cy = target.y + target.size / 2;
    const r = target.size / 2;
    return (x - cx) ** 2 + (y - cy) ** 2 <= r * r;
  }
  return isPointInTarget(x, y, target);
}

