export function scoreReaction(m) {
  const accuracy = pct(m.hitRate) - Math.min(25, m.falseTaps * 3);
  const speed = speedScore(m.avgReaction);
  const stability = clamp(
    100 - (m.stdReaction / 2.5),
    0,
    100
  );
  const total = Math.round(
    clamp(accuracy, 0, 100) * 0.35 + speed * 0.4 + stability * 0.25
  );
  return {
    total,
    accuracy: Math.round(clamp(accuracy, 0, 100)),
    speed,
    stability: Math.round(stability)
  };
}

/** 节奏测试综合分。 */
export function scoreRhythm(m) {
  const accuracy = pct(m.hitRate) - Math.min(20, m.extraTaps * 3);
  const timing = clamp(100 - m.meanAbsDelta / 3, 0, 100);
  const stability = clamp(100 - m.stdDelta / 2.5, 0, 100);
  const total = Math.round(
    clamp(accuracy, 0, 100) * 0.3 + timing * 0.4 + stability * 0.3
  );
  return {
    total,
    accuracy: Math.round(clamp(accuracy, 0, 100)),
    timing: Math.round(timing),
    stability: Math.round(stability)
  };
}

/** 双任务综合分。 */
export function scoreDual(m) {
  const rhythm = m.rhythm ? scoreRhythm(m.rhythm) : { total: 0 };
  const reaction = m.reaction ? scoreReaction(m.reaction) : { total: 0 };
  const interferencePenalty = clamp(m.interference * 1.5, 0, 40);
  const total = Math.round(
    clamp((rhythm.total + reaction.total) / 2 - interferencePenalty, 0, 100)
  );
