export const DEFAULT_SETTINGS = Object.freeze({
  audioLatencyMs: 40,
  inputLatencyCompMs: 0,
  bpm: 120,
  subdivision: 1,
  durationSec: 30,
  difficulty: 'normal',
  inputDevice: 'keyboard',
  volume: 0.7
});

export const DIFFICULTY_OPTIONS = [
  { value: 'easy', label: '简单' },
  { value: 'normal', label: '普通' },
  { value: 'hard', label: '困难' }
];

export const DURATION_OPTIONS = [15, 30, 45, 60, 90, 120];

export function sanitizeSettings(input) {
  if (!input || typeof input !== 'object') return { ...DEFAULT_SETTINGS };
  const num = (v, d, min, max) => {
    const n = Number(v);
    if (!Number.isFinite(n)) return d;
    return Math.min(max, Math.max(min, n));
  };
  return {
    audioLatencyMs: num(input.audioLatencyMs, DEFAULT_SETTINGS.audioLatencyMs, 0, 1000),
    inputLatencyCompMs: num(input.inputLatencyCompMs, DEFAULT_SETTINGS.inputLatencyCompMs, -300, 300),
    bpm: Math.round(num(input.bpm, DEFAULT_SETTINGS.bpm, 30, 300)),
    subdivision: [1, 2, 4].includes(Number(input.subdivision))
      ? Number(input.subdivision)
      : DEFAULT_SETTINGS.subdivision,
    durationSec: DURATION_OPTIONS.includes(Number(input.durationSec))
      ? Number(input.durationSec)
      : DEFAULT_SETTINGS.durationSec,
    difficulty: ['easy', 'normal', 'hard'].includes(input.difficulty)
      ? input.difficulty
      : DEFAULT_SETTINGS.difficulty,
    inputDevice: ['keyboard', 'mouse'].includes(input.inputDevice)
      ? input.inputDevice
      : DEFAULT_SETTINGS.inputDevice,
    volume: num(input.volume, DEFAULT_SETTINGS.volume, 0, 1)
  };
}

export const DEFAULT_STORE = Object.freeze({
  version: 1,
  settings: { ...DEFAULT_SETTINGS },
  presets: [],
