    );
    pushIf(
      tips,
      inputLatencyMs > 60,
      `测得输入延迟 ${Math.round(inputLatencyMs)}ms 偏高，可尝试更换键盘或关闭鼠标指针加速。`
    );
    pushIf(
      tips,
      audioLatencyMs <= 80 && inputLatencyMs <= 60,
      `延迟表现良好（音频 ${Math.round(audioLatencyMs)}ms / 输入 ${Math.round(inputLatencyMs)}ms），可直接开始训练。`
    );
