      );
    }
  }

  if (type === 'reaction' || type === 'dual') {
    const r = result.metrics.reaction;
    if (r && r.hits) {
      pushIf(
        tips,
        r.avgReaction > 420,
        `平均反应 ${Math.round(r.avgReaction)}ms 偏慢，建议降低目标出现频率，从简单难度开始练习。`
      );
      pushIf(
        tips,
        r.avgReaction <= 260 && r.bestReaction <= 200,
