      );
      pushIf(
        tips,
        r.stdReaction > 120,
        `反应时间波动大（标准差 ${Math.round(r.stdReaction)}ms），注意保持视线覆盖整个目标区域。`
      );
      pushIf(
        tips,
        r.falseTaps >= 3,
        `误触 ${r.falseTaps} 次较多，请等目标完全出现后再动作，避免提前点击。`
      );
      pushIf(
        tips,
        r.misses > Math.max(2, r.totalTargets * 0.2),
        `漏点 ${r.misses} 个偏多，目标可能过快，建议降低难度或拉长测试间隔。`
      );
    }
  }

  if (type === 'dual') {
    const interference = result.metrics.interference;
    const loss = result.metrics.switchLoss;
    pushIf(
      tips,
      interference >= 15 || loss > 60,
      `双任务下表现下降 ${interference.toFixed(0)}%、切换损失 ${Math.round(loss)}ms，干扰明显，建议先分别单练再合并。`
    );
    pushIf(
      tips,
      interference < 8,
      `双任务干扰仅 ${interference.toFixed(0)}%，注意分配能力良好，可以提高节奏或目标密度。`
    );
  }

  if (type === 'vigilance') {
    const m = result.metrics;
    pushIf(
      tips,
      m.hitDrop >= 15 || m.rtDrift >= 60,
      `后半段命中率下降 ${m.hitDrop.toFixed(0)}%、反应慢了 ${Math.round(m.rtDrift)}ms，出现疲劳迹象，建议缩短训练或安排休息。`
    );
    pushIf(
      tips,
      m.secondHalf.falseTaps > m.firstHalf.falseTaps + 1,
      `后半段误触增多（${m.firstHalf.falseTaps} → ${m.secondHalf.falseTaps}），注意力控制能力下降。`
    );
    pushIf(
      tips,
      m.hitDrop < 6 && m.rtDrift < 25,
      `前后半段表现稳定（命中率波动 ${m.hitDrop.toFixed(0)}%、反应漂移 ${Math.round(m.rtDrift)}ms），持续注意能力良好。`
    );
  }

  if (!tips.length) {
    tips.push('完成了一次有效测试，建议多跑几轮对比数据变化，再逐步提高难度。');
  }
  return tips;
}

