/**
 * Web Audio 节拍器：提前调度的短敲击音（click）+ 可选视觉回调。
 */
export function isAudioSupported() {
  return (
    typeof window !== 'undefined' &&
    (window.AudioContext || window.webkitAudioContext)
  );
}

export class AudioEngine {
  constructor(volume = 0.7) {
    this.ctx = null;
    this.volume = volume;
  }

  async ensureContext() {
    if (!this.ctx) {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      this.ctx = new Ctx();
    }
    if (this.ctx.state === 'suspended') {
      try {
        await this.ctx.resume();
      } catch {
        /* 某些浏览器需要用户手势，失败时由调用方重试 */
      }
    }
    return this.ctx;
  }

  get currentTime() {
    return this.ctx ? this.ctx.currentTime : 0;
  }

  /**
   * 调度一个 click。
   * @param whenCtx 目标时刻（AudioContext 时间，秒）
   * @param accented 是否重音拍
   */
  scheduleClick(whenCtx, accented = false) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = accented ? 'triangle' : 'square';
    osc.frequency.value = accented ? 1500 : 1000;
    const peak = this.volume * (accented ? 0.55 : 0.32);
    gain.gain.setValueAtTime(0, whenCtx);
    gain.gain.linearRampToValueAtTime(peak, whenCtx + 0.002);
    gain.gain.exponentialRampToValueAtTime(0.0001, whenCtx + 0.05);
    osc.connect(gain).connect(ctx.destination);
    osc.start(whenCtx);
    osc.stop(whenCtx + 0.06);
  }

  async suspend() {
    if (this.ctx && this.ctx.state === 'running') {
      try {
        await this.ctx.suspend();
      } catch {
        /* ignore */
      }
    }
  }

  async resume() {
    await this.ensureContext();
  }

  dispose() {
    if (this.ctx) {
      this.ctx.close().catch(() => {});
      this.ctx = null;
    }
  }
}

