/**
 * 延迟校准：视觉提示阶段估计输入延迟，节拍声音阶段估计输入+音频总延迟，
 * 二者之差即音频输出延迟。
 */
import { mean, stdDev, minAbs } from '../core/time.js';
import { AudioEngine } from './audio.js';

const BEATS_PER_PHASE = 8;

export class CalibrationRunner {
  constructor({ bpm, volume = 0.7, onEvent }) {
    this.bpm = bpm;
    this.intervalMs = 60000 / bpm;
    this.onEvent = onEvent ?? (() => {});
    this.audio = new AudioEngine(volume);
    this.state = 'idle';
    this.phase = 'visual';
    this.beats = [];
    this.visualDeltas = [];
    this.audioDeltas = [];
    this._startTime = 0;
    this._nextBeat = 0;
    this._consumed = new Set();
    this._raf = 0;
    this._windowMs = 260;
  }

  async start() {
    await this.audio.ensureContext();
    this.state = 'running';
    this._startTime = performance.now();
    this._ctxZero = this.audio.currentTime;
    this._buildPhase('visual');
    const loop = () => {
      if (this.state !== 'running') return;
      this._tick();
      this._raf = requestAnimationFrame(loop);
    };
    this._raf = requestAnimationFrame(loop);
    this.onEvent({ kind: 'phase', phase: 'visual' });
  }

  _buildPhase(phase) {
    this.phase = phase;
    this.beats = [];
    for (let i = 0; i < BEATS_PER_PHASE; i += 1) {
      this.beats.push(this.intervalMs * (i + 1));
    }
    this._nextBeat = 0;
    this._consumed = new Set();
    this._phaseStart = performance.now();
    if (phase === 'audio') this._ctxZero = this.audio.currentTime;
    this.onEvent({ kind: 'phase', phase, beats: this.beats });
  }

  _tick() {
    const elapsed = performance.now() - this._phaseStart;
    while (this._nextBeat < this.beats.length) {
      const bt = this.beats[this._nextBeat];
      if (bt > elapsed + 150) break;
      if (this.phase === 'audio') {
        const ctxTime = this._ctxZero + bt / 1000;
        this.audio.scheduleClick(ctxTime, this._nextBeat % 4 === 0);
      }
      this.onEvent({
        kind: 'beat',
        phase: this.phase,
        index: this._nextBeat,
        time: bt,
        flash: this.phase === 'visual'
      });
      this._nextBeat += 1;
    }
    for (let i = 0; i < this.beats.length; i += 1) {
      if (!this._consumed.has(i) && elapsed - this.beats[i] > this._windowMs) {
        this._consumed.add(i);
        this.onEvent({ kind: 'miss', phase: this.phase, index: i });
      }
    }
    const need = this.phase === 'visual' ? this.visualDeltas : this.audioDeltas;
    if (need.length >= BEATS_PER_PHASE) {
      this._finishPhase();
      return;
    }
    if (elapsed > this.beats[this.beats.length - 1] + this._windowMs + 800) {
      this._finishPhase();
    }
  }

  _finishPhase() {
    cancelAnimationFrame(this._raf);
    if (this.phase === 'visual') {
      this.state = 'between';
      this.onEvent({ kind: 'phaseDone', phase: 'visual', deltas: [...this.visualDeltas] });
    } else {
      this._complete();
    }
  }

  async startAudioPhase() {
    if (this.state !== 'between') return;
    this.state = 'running';
    await this.audio.ensureContext();
    this._buildPhase('audio');
    const loop = () => {
      if (this.state !== 'running') return;
      this._tick();
      this._raf = requestAnimationFrame(loop);
    };
    this._raf = requestAnimationFrame(loop);
  }

  handleTap(perf = performance.now()) {
    if (this.state !== 'running') return;
    const elapsed = perf - this._phaseStart;
    let best = -1;
    let bestAbs = Infinity;
    for (let i = 0; i < this.beats.length; i += 1) {
      if (this._consumed.has(i)) continue;
      const d = Math.abs(elapsed - this.beats[i]);
      if (d < bestAbs) {
        bestAbs = d;
        best = i;
      }
    }
    if (best === -1) return;
    const signed = elapsed - this.beats[best];
    this._consumed.add(best);
    const deltas = this.phase === 'visual' ? this.visualDeltas : this.audioDeltas;
    deltas.push(signed);
    this.onEvent({
      kind: 'tap',
      phase: this.phase,
      index: best,
      delta: signed,
      count: deltas.length
    });
  }

  _complete() {
    this.state = 'finished';
    cancelAnimationFrame(this._raf);
    const inputLatencyMs = mean(this.visualDeltas);
    const totalMs = mean(this.audioDeltas);
    const audioLatencyMs = Math.max(0, totalMs - inputLatencyMs);
    const result = {
      type: 'calibration',
      bpm: this.bpm,
      finishedAt: Date.now(),
      inputLatencyMs: Math.round(inputLatencyMs),
      audioLatencyMs: Math.round(audioLatencyMs),
      visual: {
        deltas: [...this.visualDeltas],
        mean: Math.round(mean(this.visualDeltas)),
        std: Math.round(stdDev(this.visualDeltas)),
        best: Math.round(minAbs(this.visualDeltas))
      },
      auditory: {
        deltas: [...this.audioDeltas],
        mean: Math.round(mean(this.audioDeltas)),
        std: Math.round(stdDev(this.audioDeltas)),
        best: Math.round(minAbs(this.audioDeltas))
      }
    };
    this.onEvent({ kind: 'complete', result });
    return result;
  }

  dispose() {
    this.state = 'aborted';
    cancelAnimationFrame(this._raf);
    this.audio.dispose();
  }
}

