+            class: 'btn',
+            text: '取消',
+            onClick: () => {
+              overlay.remove();
+              resolve(false);
+            }
+          }),
+          el('button', {
+            class: danger ? 'btn btn-danger' : 'btn btn-primary',
+            text: confirmText,
+            onClick: () => {
+              overlay.remove();
+              resolve(true);
+            }
+          })
+      ])
+    ]);
+    overlay.append(dialog);
+    overlay.addEventListener('mousedown', (e) => {
+      if (e.target === overlay) {
+        overlay.remove();
