html, body {
  margin: 0;
  padding: 0;
  background: radial-gradient(1200px 700px at 70% -10%, #1a2340 0%, var(--bg) 55%);
  color: var(--text);
  min-height: 100vh;
}
#app { min-height: 100vh; display: flex; flex-direction: column; }
.app-header {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 12px 28px;
  border-bottom: 1px solid var(--border);
  background: rgba(14, 17, 24, 0.85);
  backdrop-filter: blur(8px);
  position: sticky;
  top: 0;
  z-index: 20;
}
.brand { font-weight: 700; font-size: 17px; cursor: pointer; white-space: nowrap; }
.brand .dot { color: var(--primary); }
.nav { display: flex; gap: 4px; flex-wrap: wrap; }
.nav a {
  color: var(--text-dim);
  text-decoration: none;
  padding: 6px 12px;
  border-radius: 8px;
  font-size: 14px;
}
.nav a:hover { color: var(--text); background: var(--bg-panel-2); }
.nav a.active { color: #fff; background: var(--primary-2); }
.header-spacer { flex: 1; }
.badge {
  font-size: 12px;
  color: var(--text-dim);
  border: 1px solid var(--border);
  padding: 4px 10px;
  border-radius: 999px;
}
.container { width: 100%; max-width: 1080px; margin: 0 auto; padding: 28px; flex: 1; }
.wide { max-width: 1200px; }
h1 { font-size: 28px; margin: 0 0 8px; }
h2 { font-size: 20px; margin: 0 0 14px; }
h3 { font-size: 16px; margin: 18px 0 10px; }
p { line-height: 1.7; }
.muted { color: var(--text-dim); }
.small { font-size: 13px; }
.card {
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  margin-bottom: 18px;
}
.grid { display: grid; gap: 16px; }
.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
@media (max-width: 820px) {
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
}
.btn {
  appearance: none;
  border: 1px solid var(--border);
  background: var(--bg-panel-2);
  color: var(--text);
  padding: 9px 18px;
  border-radius: 9px;
  font-size: 14px;
  cursor: pointer;
}
.btn:hover { border-color: #3d4b68; }
.btn:active { transform: translateY(1px); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; }
.btn-primary { background: var(--primary-2); border-color: var(--primary); color: #fff; }
.btn-primary:hover { background: var(--primary); }
.btn-danger { background: #3a1d22; border-color: #6b2c33; color: #ffb4b7; }
.btn-danger:hover { background: #4d242b; }
.btn-ghost { background: transparent; }
.btn-lg { padding: 13px 26px; font-size: 16px; border-radius: 11px; }
.btn-row { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 8px; }
.form-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 0;
  border-bottom: 1px dashed var(--border);
}
.form-row:last-child { border-bottom: none; }
.form-row label { color: var(--text-dim); font-size: 14px; }
.form-row .ctrl { display: flex; align-items: center; gap: 10px; }
input[type='number'], input[type='text'], select {
  background: var(--bg);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: 8px;
  padding: 7px 10px;
  font-size: 14px;
  min-width: 120px;
}
input[type='range'] { width: 180px; accent-color: var(--primary); }
.seg { display: inline-flex; border: 1px solid var(--border); border-radius: 9px; overflow: hidden; }
.seg button { background: transparent; color: var(--text-dim); border: 0; padding: 7px 14px; cursor: pointer; font-size: 13px; }
.seg button.on { background: var(--primary-2); color: #fff; }
.stat {
  background: var(--bg-panel-2);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px 16px;
}
.stat .k { color: var(--text-dim); font-size: 12.5px; }
.stat .v { font-size: 24px; font-weight: 700; margin-top: 4px; }
.stat .sub { color: var(--text-dim); font-size: 12px; margin-top: 2px; }
.v.good { color: var(--good); }
.v.warn { color: var(--warn); }
.v.bad { color: var(--bad); }
.hero { text-align: center; padding: 60px 24px 40px; }
.hero h1 {
  font-size: 40px;
  background: linear-gradient(90deg, #8ab4ff, #c59dff);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hero p { color: var(--text-dim); max-width: 640px; margin: 10px auto 26px; }
.test-types { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-top: 26px; }
@media (max-width: 900px) { .test-types { grid-template-columns: repeat(2, 1fr); } }
.type-card {
  text-align: left;
  padding: 20px;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: var(--bg-panel);
  cursor: pointer;
  color: var(--text);
}
.type-card:hover { border-color: var(--primary); transform: translateY(-2px); }
.type-card .icon { font-size: 26px; }
.type-card .name { font-weight: 700; margin: 8px 0 4px; }
.type-card .desc { color: var(--text-dim); font-size: 13px; line-height: 1.5; }

