import './styles.css';
import { el, mount, toast } from './ui/dom.js';
import {
  CorruptDataError,
  loadStore,
  resetStore,
  saveStore
} from './core/storage.js';
import { homePage } from './ui/pages/home.js';
import { settingsPage } from './ui/pages/settings.js';
import { calibrationPage } from './ui/pages/calibration.js';
import { selectPage } from './ui/pages/select.js';
import { testPage } from './ui/pages/test.js';
import { resultPage } from './ui/pages/result.js';
import { recordsPage } from './ui/pages/records.js';

const NAV = [
  { hash: '#/', label: '开始' },
  { hash: '#/settings', label: '设置' },
  { hash: '#/calibration', label: '校准' },
  { hash: '#/select', label: '测试' },
  { hash: '#/records', label: '记录' }
];

function parseHash() {
  const raw = location.hash || '#/';
  const [path, query = ''] = raw.slice(1).split('?');
  const params = Object.fromEntries(new URLSearchParams(query));
  return { path: path || '/', params };
}

export function navigate(hash) {
  if (location.hash === hash) {
    render();
  } else {
    location.hash = hash;
  }
}

function parseQuery() {
  const raw = location.hash || '#/';
  const query = raw.slice(1).split('?')[1] || '';
  return Object.fromEntries(new URLSearchParams(query));
}

function pathOf() {
  const raw = location.hash || '#/';
  return raw.slice(1).split('?')[0] || '/';
}

const app = document.getElementById('app');

let store;
try {
  store = loadStore(localStorage);
} catch (err) {
  store = null;
  setTimeout(() => showCorruptScreen(err), 0);
}

export function getStore() {
  return store;
}

export function updateStore(mutator) {
  const next = mutator(store);
  store = saveStore(next, localStorage);
  return store;
}

export function replaceStore(next) {
  store = saveStore(next, localStorage);
}

async function showCorruptScreen(err) {
  mount(
    app,
    el('div', { class: 'container' }, [
      el('div', { class: 'card danger-zone' }, [
        el('h1', { text: '本地数据损坏' }),
        el('p', {
          class: 'muted',
          text: '读取浏览器本地保存的设置、配置或记录时解析失败。你可以尝试把损坏的原始数据导出留存，或直接清空后恢复为默认状态。'
        }),
        el('pre', {
          class: 'small muted',
          style: {
            whiteSpace: 'pre-wrap',
            background: 'var(--bg)',
            padding: '12px',
            borderRadius: '8px',
            border: '1px solid var(--border)'
          },
          text: err instanceof CorruptDataError ? err.rawSnippet : String(err)
        }),
        el('div', { class: 'btn-row' }, [
          el('button', {
            class: 'btn',
            text: '导出损坏的原始数据',
            onClick: () => {
              const text = localStorage.getItem('rrt-store-v1') || '';
              const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `corrupt-data-${Date.now()}.txt`;
              a.click();
              setTimeout(() => URL.revokeObjectURL(url), 1000);
            }
          }),
          el('button', {
            class: 'btn btn-danger',
            text: '清空数据并恢复默认',
            onClick: () => {
              store = resetStore(localStorage);
              toast('已清空损坏数据并恢复默认', 'good');
              navigate('#/');
              setTimeout(render, 0);
            }
          })
        ])
      ])
    ])
  );
}

function shell(content, { wide = false } = {}) {
  const { path } = parseHash();
  const header = el('header', { class: 'app-header' }, [
    el('div', {
      class: 'brand',
      html: '节奏<span class="dot">·</span>反应训练',
      onClick: () => navigate('#/')
    }),
    el('nav', { class: 'nav' },
      NAV.map((item) =>
        el('a', {
          href: item.hash,
          text: item.label,
          class: path === item.hash.slice(1) ? 'active' : ''
        })
      )
    ),
    el('div', { class: 'header-spacer' }),
    el('span', { class: 'badge', text: `记录 ${store.records.length} 条` })
  ]);
  const main = el('main', { class: wide ? 'container wide' : 'container' }, [content]);
  mount(app, [header, main]);
}

export function render() {
  if (!store) return;
  const path = pathOf();
  const params = parseQuery();
  const ctx = { store, params, navigate, updateStore, replaceStore, render };
  try {
    if (path === '/' || path === '') {
      shell(homePage(ctx));
    } else if (path === '/settings') {
      shell(settingsPage(ctx));
    } else if (path === '/calibration') {
      shell(calibrationPage(ctx), { wide: true });
    } else if (path === '/select') {
      shell(selectPage(ctx));
    } else if (path === '/test') {
      shell(testPage(ctx), { wide: true });
    } else if (path === '/result') {
      shell(resultPage(ctx), { wide: true });
    } else if (path === '/record') {
      shell(recordsPage(ctx), { wide: true });
    } else {
      shell(homePage(ctx));
    }
  } catch (err) {
    console.error(err);
    shell(
      el('div', { class: 'card' }, [
        el('h1', { text: '页面渲染出错' }),
        el('p', { class: 'muted', text: String(err && err.message ? err.message : err) }),
        el('button', { class: 'btn btn-primary', text: '返回开始页', onClick: () => navigate('#/') })
      ])
    );
  }
}

window.addEventListener('hashchange', render);
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', render);
} else {
  render();
}

export { toast };

