            max: 1,
            step: 0.01,
            value: draft.volume,
            onInput: (e) => {
              draft.volume = Number(e.target.value);
              volumeLabel.textContent = `${Math.round(draft.volume * 100)}%`;
            }
          }),
          volumeLabel
        ])
      ]),
      el('div', { class: 'btn-row' }, [
        el('button', {
          class: 'btn btn-primary',
          text: '保存设置',
          onClick: () => {
            updateStore((st) => ({ ...st, settings: sanitizeSettings(draft) }));
            toast('设置已保存，刷新浏览器后仍会保留', 'good');
            navigate('#/');
          }
        }),
        el('button', {
          class: 'btn',
          text: '恢复默认设置',
          onClick: async () => {
            const ok = await confirmDialog('确定恢复为默认基础设置？已保存的配置与记录不受影响。');
            if (!ok) return;
            updateStore((st) => ({ ...st, settings: { ...DEFAULT_SETTINGS } }));
            toast('已恢复默认设置', 'good');
            navigate('#/settings');
          }
        })
      ])
    ]),
    presetsCard,
    el('div', { class: 'card danger-zone' }, [
      el('h2', { text: '数据管理' }),
      el('div', { class: 'btn-row' }, [
        el('button', {
          class: 'btn btn-danger',
          text: '清空全部本地数据（设置/配置/记录/校准）',
          onClick: async () => {
            const ok = await confirmDialog(
              '将清空所有设置、训练配置、校准结果与测试记录，且不可恢复。确定继续？',
              { danger: true, confirmText: '全部清空' }
            );
            if (!ok) return;
            resetStore(localStorage);
            toast('本地数据已全部清空', 'good');
            window.location.hash = '#/';
            window.location.reload();
          }
        }),
        el('button', {
          class: 'btn',
          text: '模拟本地数据损坏（演示错误恢复）',
          onClick: async () => {
            const ok = await confirmDialog(
              '会写入一段无法解析的内容覆盖本地数据，随后出现损坏恢复页面。确定继续？',
              { danger: true, confirmText: '模拟损坏' }
            );
            if (!ok) return;
            localStorage.setItem('rrt-store-v1', '{ corrupted-json !!! ');
            window.location.reload();
          }
        })
      ])
    ])
  ]);

  const listHolder = page.querySelector('#preset-list');
  listHolder.append(...renderPresetList(store, updateStore, navigate));
  return page;
}

function describeSettings(s) {
  return `${s.bpm} BPM · ${s.subdivision}分音 · ${s.durationSec}s · ${
    { easy: '简单', normal: '普通', hard: '困难' }[s.difficulty]
  } · ${s.inputDevice === 'keyboard' ? '键盘' : '鼠标'}`;
}

function renderPresetList(store, updateStore, navigate) {
  if (!store.presets.length) {
    return [el('p', { class: 'small muted', text: '暂无保存的配置。' })];
  }
  return store.presets.map((p) =>
    el('div', { class: 'preset-item' }, [
      el('div', {}, [
        el('div', { text: p.name, style: { fontWeight: '600' } }),
        el('div', { class: 'meta', text: describeSettings(p.settings) })
      ]),
      el('div', { class: 'btn-row', style: { margin: '0' } }, [
        el('button', {
          class: 'btn btn-primary',
          text: '用此配置测试',
          onClick: () => {
            updateStore((st) => ({ ...st, settings: sanitizeSettings(p.settings) }));
            navigate('#/select');
          }
        }),
        el('button', {
          class: 'btn btn-danger',
          text: '删除',
          onClick: async () => {
            const ok = await confirmDialog(`删除配置「${p.name}」？`);
            if (!ok) return;
            updateStore((st) => deletePreset(st, p.id));
            navigate('#/settings');
          }
        })
      ])
    ])
  );
}

