import { el } from '../dom.js';

const TYPES = [
  {
    value: 'rhythm',
    icon: '🥁',
    name: '节奏跟随',
    desc: '持续播放带律动变化的节拍，按窗口判定命中，分析抢拍/拖拍与稳定性。'
  },
  {
    value: 'reaction',
    icon: '👁️',
    name: '视觉反应',
    desc: '随机位置、大小、颜色的目标，尽快点击或按键，分析反应分布与误触。'
  },
  {
    value: 'dual',
    icon: '🔀',
    name: '双任务',
    desc: '一边跟拍一边处理视觉目标，量化任务切换损失与互相干扰。'
  },
  {
    value: 'vigilance',
    icon: '⏳',
    name: '持续注意与疲劳',
    desc: '长时程、频率渐快并穿插需抑制的干扰刺激，分前后半段统计。'
  }
];

export function selectPage({ store, navigate }) {
  const s = store.settings;

  const presetOptions = (includeEmpty) => {
    const opts = [];
    if (includeEmpty) opts.push(el('option', { value: '', text: '— 不使用（用当前设置） —' }));
    opts.push(
      ...store.presets.map((p) => el('option', { value: p.id, text: p.name }))
    );
    return opts;
  };

  const compareA = el('select', {}, presetOptions(true));
  const compareB = el('select', {}, presetOptions(true));

  return el('div', {}, [
    el('h1', { text: '选择测试' }),
    el('p', {
      class: 'muted',
      text: `当前配置：${s.bpm} BPM · ${s.durationSec} 秒 · ${
        { easy: '简单', normal: '普通', hard: '困难' }[s.difficulty]
      } · ${s.inputDevice === 'keyboard' ? '键盘' : '鼠标'}。开始前会有 3 秒倒计时，测试中可暂停 / 继续 / 重新开始。`
    }),
    el('div', { class: 'btn-row mb' }, [
      el('button', { class: 'btn', text: '修改设置', onClick: () => navigate('#/settings') }),
      el('button', { class: 'btn', text: '延迟校准', onClick: () => navigate('#/calibration') })
    ]),
    el('div', { class: 'test-types', style: { gridTemplateColumns: 'repeat(2, 1fr)' } },
      TYPES.map((t) =>
        el('button', {
          class: 'type-card',
          onClick: () => navigate(`#/test?type=${t.value}`)
        }, [
          el('div', { class: 'icon', text: t.icon }),
          el('div', { class: 'name', text: t.name }),
          el('div', { class: 'desc', text: t.desc })
        ])
      )
    ),
    el('div', { class: 'card mt' }, [
      el('h2', { text: '训练方案对比' }),
      el('p', {
        class: 'small muted',
        text: '选择两组已保存的配置，系统将使用相同目标数量、规则与时长连续各测一次，结果页按命中、反应、节奏偏差、持续注意逐项对比。'
      }),
      el('div', { class: 'grid grid-2' }, [
        el('div', { class: 'form-row' }, [
          el('label', { text: '配置 A' }),
          compareA
        ]),
        el('div', { class: 'form-row' }, [
          el('label', { text: '配置 B' }),
          compareB
        ])
      ]),
      el('div', { class: 'form-row mt' }, [
        el('label', { text: '对比的测试项目' }),
        el('div', { class: 'seg', id: 'compare-type' },
          TYPES.map((t, i) =>
            el('button', {
              type: 'button',
              class: i === 0 ? 'on' : '',
              text: t.name,
              dataset: { type: t.value },
              onClick: (e) => {
                e.currentTarget.parentElement.querySelectorAll('button').forEach((b) =>
                  b.classList.remove('on')
                );
                e.currentTarget.classList.add('on');
              }
            })
          )
        )
      ]),
      el('div', { class: 'btn-row' }, [
        el('button', {
          class: 'btn btn-primary',
          text: '开始对比（连续两次）',
          onClick: () => {
            const a = compareA.value;
            const b = compareB.value;
            if (!a || !b) {
              alert ? null : null;
              const box = document.createElement('div');
              box.className = 'toast show bad';
              return;
            }
            if (a === b) {
              const note = document.getElementById('compare-note');
              note.textContent = '请选择两组不同的配置。';
              note.className = 'small bad';
              return;
            }
            const typeBtn = document.querySelector('#compare-type button.on');
            const type = typeBtn.dataset.type;
            navigate(`#/test?type=${type}&compareA=${a}&compareB=${b}`);
          }
        })
      ]),
      el('p', { id: 'compare-note', class: 'small mt' })
    ])
  ]);
}

