import { el, toast, fmtTime } from '../dom.js';
import {
  getPendingRun,
  getPendingCompare
} from '../state.js';
import { generateAdvice } from '../../core/advice.js';
import { addRecord } from '../../core/storage.js';
import {
  metricsGrid,
  scoreCard,
  reactionHistogram,
  rhythmDeviationChart
} from '../result-views.js';

const TYPE_LABEL = {
  rhythm: '节奏跟随',
  reaction: '视觉反应',
  dual: '双任务',
  vigilance: '持续注意与疲劳'
};

export function resultPage({ store, params, updateStore, navigate }) {
  if (params.mode === 'compare') {
    const runs = getPendingCompare();
    if (!runs || runs.length !== 2) return missingData(navigate);
    return compareView(runs, store, updateStore, navigate);
  }
  const backRecord = window.__rrtBackRecord || null;
  if (params.from === 'compare' && backRecord) {
    window.__rrtBackRecord = null;
    return singleView(backRecord, store, updateStore, navigate, true);
  }
  const record = getPendingRun() || store.records.find((r) => r.id === params.id);
  if (!record) return missingData(navigate);
  return singleView(record, store, updateStore, navigate);
}

function missingData(navigate) {
  return el('div', { class: 'card' }, [
    el('h1', { text: '没有可显示的结果' }),
    el('p', { class: 'muted', text: '结果可能已在刷新后清空（历史记录中已保存的记录不受影响）。' }),
    el('button', { class: 'btn btn-primary', text: '去测试选择', onClick: () => navigate('#/select') })
  ]);
}

function singleView(record, store, updateStore, navigate, fromCompare = false) {
  const advice = generateAdvice(record, store.settings);
  const alreadySaved = store.records.some((r) => r.id === record.id);
  const reactions = record.metrics.reactionTimes || [];
