  const saveButton = alreadySaved
    ? el('span', { class: 'tag good', text: '已保存到历史记录' })
    : el('button', {
        class: 'btn',
        text: '保存本次记录',
        onClick: () => {
          updateStore((st) => addRecord(st, record));
