          navigate(`#/result?id=${record.id}`);
        }
      });

  return el('div', {}, [
    el('h1', { text: `${TYPE_LABEL[record.type] || '测试'} 结果` }),
    el('p', {
      class: 'muted small',
      text: `${record.label || ''} · 完成于 ${fmtTime(record.finishedAt)} · ${record.settings.durationSec} 秒 · ${
        { easy: '简单', normal: '普通', hard: '困难' }[record.settings.difficulty]
      } · ${record.settings.bpm} BPM`
    }),
