        el('h2', { text: '反应速度分布' }),
        reactionHistogram(reactions)
      ]),
    record.metrics.rhythm &&
      deltas.length > 0 &&
      el('div', { class: 'card' }, [
        el('h2', { text: '节奏偏差序列' }),
        el('p', { class: 'small muted', text: '橙点=抢拍（负偏差），绿点=拖拍（正偏差），虚线为零偏差。' }),
        rhythmDeviationChart(deltas)
      ]),
    el('div', { class: 'card' }, [
      el('h2', { text: '基于本次数据的训练建议' }),
      el('ul', { class: 'advice' }, advice.map((t) => el('li', { text: t })))
    ]),
    el('div', { class: 'btn-row' }, [
      el('button', {
        class: 'btn btn-primary',
        text: '重新测试',
        onClick: () => navigate(`#/test?type=${record.type}`)
      }),
      el('button', { class: 'btn', text: '返回设置', onClick: () => navigate('#/settings') }),
      el('button', { class: 'btn', text: '测试选择', onClick: () => navigate('#/select') }),
      fromCompare
        ? el('button', { class: 'btn', text: '返回对比结果', onClick: () => navigate('#/result?mode=compare') })
        : null,
      saveButton
    ])
  ]);
}

