import { el, confirmDialog, toast, fmtTime, fmtMs, fmtPct } from '../dom.js';
import {
  clearRecords,
  deleteRecord,
  downloadText,
  recordsToCsv
} from '../../core/storage.js';

const TYPE_LABEL = {
  rhythm: '节奏跟随',
  reaction: '视觉反应',
  dual: '双任务',
  vigilance: '持续注意'
};

export function recordsPage({ store, updateStore, params, navigate }) {
  if (params.id) {
    const record = store.records.find((r) => r.id === params.id);
    if (record) return detailView(record, navigate);
  }

  const exportJsonBtn = el('button', {
    class: 'btn',
    text: '导出 JSON',
    disabled: !store.records.length,
    onClick: () => {
      downloadText(
        `rhythm-reaction-records-${Date.now()}.json`,
        JSON.stringify(store.records, null, 2)
      );
      toast('已导出 JSON 文件', 'good');
    }
  });
  const exportCsvBtn = el('button', {
    class: 'btn',
    text: '导出 CSV',
    disabled: !store.records.length,
    onClick: () => {
      downloadText(
        `rhythm-reaction-records-${Date.now()}.csv`,
        recordsToCsv(store.records),
        'text/csv'
      );
      toast('已导出 CSV 文件', 'good');
    }
  });

  const body = store.records.length
    ? el('table', {}, [
        el('thead', {},
          el('tr', {}, [
            el('th', { text: '时间' }),
            el('th', { text: '类型' }),
            el('th', { text: '配置' }),
            el('th', { text: '综合分' }),
            el('th', { text: '命中率' }),
            el('th', { text: '反应/偏差' }),
            el('th', { text: '操作' })
          ])
        ),
        el('tbody', {}, store.records.map(recordRow))
      ])
    : el('p', { class: 'muted', text: '还没有已保存的测试记录。完成一次测试并在结果页点击“保存本次记录”即可。' });

  function recordRow(r) {
    const react = r.metrics.reaction;
    const rhy = r.metrics.rhythm;
    return el('tr', {}, [
      el('td', { class: 'small', text: fmtTime(r.finishedAt) }),
      el('td', {}, el('span', { class: 'tag', text: TYPE_LABEL[r.type] || r.type })),
      el('td', {
        class: 'small muted',
        text: `${r.settings.bpm} BPM · ${r.settings.durationSec}s · ${
          { easy: '简单', normal: '普通', hard: '困难' }[r.settings.difficulty]
        }`
      }),
      el('td', {},
        el('b', {
          text: String(r.score?.total ?? '—'),
          class:
            (r.score?.total ?? 0) >= 80 ? 'good' : (r.score?.total ?? 0) >= 55 ? 'warn' : 'bad'
        })
      ),
      el('td', {
        class: 'small',
        text: react
          ? fmtPct(react.hitRate)
          : rhy
            ? fmtPct(rhy.hitRate)
            : r.type === 'vigilance'
              ? fmtPct(r.metrics.secondHalf.hitRate)
              : '—'
      }),
      el('td', {
        class: 'small',
        text: react
          ? `均 ${Math.round(react.avgReaction)}ms / 最快 ${Math.round(react.bestReaction)}ms`
          : rhy
            ? `偏差 ${rhy.meanDelta > 0 ? '+' : ''}${Math.round(rhy.meanDelta)}ms / σ ${Math.round(rhy.stdDelta)}ms`
            : '—'
      }),
      el('td', {},
        el('div', { style: { display: 'flex', gap: '6px' } }, [
          el('button', {
            class: 'btn',
            text: '详情',
            onClick: () => navigate(`#/record?id=${r.id}`)
          }),
          el('button', {
            class: 'btn btn-danger',
            text: '删除',
            onClick: async () => {
              const ok = await confirmDialog('确定删除这一条测试记录？');
              if (!ok) return;
              updateStore((st) => deleteRecord(st, r.id));
              toast('记录已删除', 'good');
              navigate('#/record');
            }
          })
        ])
      )
    ]);
  }

  return el('div', {}, [
    el('h1', { text: '测试记录' }),
    el('p', { class: 'muted', text: `共 ${store.records.length} 条记录，最多保留最近 100 条，全部持久化在浏览器本地。` }),
    el('div', { class: 'btn-row mb' }, [
      exportJsonBtn,
      exportCsvBtn,
      el('button', {
        class: 'btn btn-danger',
        text: '清空全部记录',
        disabled: !store.records.length,
        onClick: async () => {
          const ok = await confirmDialog(
            `确定清空全部 ${store.records.length} 条测试记录？设置与配置不受影响，此操作不可恢复。`,
            { danger: true, confirmText: '清空全部记录' }
          );
          if (!ok) return;
          updateStore((st) => clearRecords(st));
          toast('全部记录已清空', 'good');
          navigate('#/record');
        }
      })
    ]),
    el('div', { class: 'card' }, [body])
  ]);
}

function detailView(r, navigate) {
  const m = r.metrics;
  const rows = [];
  const add = (k, v) => rows.push(el('tr', {}, [el('td', { text: k }), el('td', { text: String(v) })]));

  add('测试类型', TYPE_LABEL[r.type] || r.type);
  add('完成时间', fmtTime(r.finishedAt));
  add('配置', `${r.settings.bpm} BPM · ${r.settings.subdivision}分音 · ${r.settings.durationSec}s · ${
    { easy: '简单', normal: '普通', hard: '困难' }[r.settings.difficulty]
  } · ${r.inputDevice || r.settings.inputDevice}`);
  add('综合分数', r.score?.total ?? '—');
  if (r.score) {
    Object.entries(r.score)
      .filter(([k]) => k !== 'total')
      .forEach(([k, v]) => add(`分项 · ${k}`, v));
  }
  if (m.rhythm) {
    add('节奏命中率', fmtPct(m.rhythm.hitRate));
    add('平均时间偏差', `${m.rhythm.meanDelta > 0 ? '+' : ''}${Math.round(m.rhythm.meanDelta)} ms`);
    add('平均绝对偏差', fmtMs(m.rhythm.meanAbsDelta));
    add('偏差标准差', fmtMs(m.rhythm.stdDelta));
    add('最快偏差', fmtMs(m.rhythm.bestDelta));
    add('漏拍 / 多余敲击', `${m.rhythm.misses} / ${m.rhythm.extraTaps}`);
    add('最长连击', m.rhythm.maxCombo);
  }
  if (m.reaction) {
    add('目标命中率', fmtPct(m.reaction.hitRate));
    add('平均反应时间', fmtMs(m.reaction.avgReaction));
    add('最快反应时间', fmtMs(m.reaction.bestReaction));
    add('反应标准差', fmtMs(m.reaction.stdReaction));
    add('漏点 / 误触', `${m.reaction.misses} / ${m.reaction.falseTaps}`);
  }
  if (r.type === 'vigilance') {
    add('前半段命中率/均反应', `${fmtPct(m.firstHalf.hitRate)} / ${Math.round(m.firstHalf.avgReaction)}ms`);
    add('后半段命中率/均反应', `${fmtPct(m.secondHalf.hitRate)} / ${Math.round(m.secondHalf.avgReaction)}ms`);
    add('命中率衰退', `${m.hitDrop} 个百分点`);
    add('反应漂移', `${Math.round(m.rtDrift)} ms`);
    add('抑制失败次数', m.noGoErrors);
  }
  if (r.type === 'dual') {
    add('任务切换损失', fmtMs(m.switchLoss));
    add('相互干扰程度', `${m.interference}%`);
  }

  return el('div', {}, [
    el('h1', { text: `记录详情 · ${TYPE_LABEL[r.type] || r.type}` }),
    el('div', { class: 'card' }, [el('table', {}, [el('tbody', {}, rows)])]),
    el('div', { class: 'btn-row' }, [
      el('button', { class: 'btn btn-primary', text: '用相同配置重新测试', onClick: () => navigate(`#/test?type=${r.type}`) }),
      el('button', { class: 'btn', text: '返回记录列表', onClick: () => navigate('#/record') })
    ])
  ]);
}

