      ? '第一阶段只看闪烁方块敲击，估计输入延迟；第二阶段只听节拍声敲击，估计输入+音频总延迟，二者之差即音频输出延迟。每阶段 8 拍。'
      : '当前浏览器不支持 Web Audio，只能进行视觉阶段以估计输入延迟；建议换用桌面版 Chrome/Edge/Firefox 后再做完整校准。'
  });
  const progressText = el('div', { class: 'hud-kv', html: '已敲击 <b>0</b>/8' });
  const deltaList = el('div', { class: 'grid grid-4', id: 'delta-list' });

  const startBtn = el('button', { class: 'btn btn-primary btn-lg', text: '开始校准' });
  const nextPhaseBtn = el('button', {
    class: 'btn btn-primary',
    text: '进入声音阶段',
    style: { display: 'none' }
  });

  const resultPanel = el('div', { id: 'cal-result' });

  const bpmSeg = el('div', { class: 'seg' },
    BPM_OPTIONS.map((b) =>
      el('button', {
        type: 'button',
        class: b === bpm ? 'on' : '',
        text: `${b} BPM`,
        onClick: (e) => {
          bpm = b;
          e.currentTarget.parentElement.querySelectorAll('button').forEach((x) => x.classList.remove('on'));
          e.currentTarget.classList.add('on');
        }
      })
    )
  );

  function tapHandler(e) {
    if (!runner) return;
    if (e.type === 'keydown' && e.code !== 'Space' && e.code !== 'Enter') return;
    if (e.type === 'keydown') e.preventDefault();
    runner.handleTap();
  }

  function resetDeltas(phase, count = 0) {
    deltaList.replaceChildren();
    progressText.innerHTML = `已敲击 <b>${count}</b>/8（${phase === 'visual' ? '看闪烁' : '听声音'}阶段）`;
  }

  function addDelta(phase, delta) {
    const tone = Math.abs(delta) < 60 ? 'good' : Math.abs(delta) < 120 ? 'warn' : 'bad';
    deltaList.append(
      el('div', { class: 'stat' }, [
        el('div', { class: 'k', text: `${phase === 'visual' ? '视觉' : '声音'} #${deltaList.children.length + 1}` }),
        el('div', { class: `v ${tone}`, style: { fontSize: '18px' }, text: `${delta > 0 ? '+' : ''}${Math.round(delta)} ms` })
      ])
    );
  }

  async function startCalibration() {
    if (runner) runner.dispose();
    resultPanel.replaceChildren();
    nextPhaseBtn.style.display = 'none';
    startBtn.disabled = true;
    runner = new CalibrationRunner({
      bpm,
      volume: store.settings.volume,
      onEvent: (ev) => handleEvent(ev)
    });
    await runner.start();
  }

  function handleEvent(ev) {
    if (ev.kind === 'phase') {
      phaseTitle.textContent = ev.phase === 'visual' ? '第一阶段：看着闪烁敲击' : '第二阶段：听声音敲击（别看方块）';
      resetDeltas(ev.phase);
      flash.classList.remove('on');
    } else if (ev.kind === 'beat') {
      if (ev.flash) {
        flash.classList.add('on');
        setTimeout(() => flash.classList.remove('on'), 130);
      }
    } else if (ev.kind === 'tap') {
      progressText.innerHTML = `已敲击 <b>${ev.count}</b>/8`;
      addDelta(ev.phase, ev.delta);
    } else if (ev.kind === 'phaseDone') {
      phaseTitle.textContent = '视觉阶段完成';
      if (audioOk) nextPhaseBtn.style.display = '';
      else finishWithoutAudio();
    } else if (ev.kind === 'complete') {
      phaseTitle.textContent = '校准完成';
      startBtn.disabled = false;
      startBtn.textContent = '重新校准';
      renderResult(ev.result);
    }
  }

  function finishWithoutAudio() {
    const input = Math.round(runner.visualDeltas.reduce((s, d) => s + d, 0) / Math.max(1, runner.visualDeltas.length));
    const result = {
      type: 'calibration',
      bpm,
      finishedAt: Date.now(),
      inputLatencyMs: input,
      audioLatencyMs: 0,
      audioSupported: false,
      visual: summarize(runner.visualDeltas),
      auditory: null
    };
    startBtn.disabled = false;
    startBtn.textContent = '重新校准';
    renderResult(result);
  }

  nextPhaseBtn.addEventListener('click', async () => {
    if (!runner) return;
    nextPhaseBtn.style.display = 'none';
    await runner.startAudioPhase();
  });
  startBtn.addEventListener('click', startCalibration);

  document.addEventListener('keydown', tapHandler);
  flash.addEventListener('pointerdown', tapHandler);

  const page = el('div', {}, [
    el('h1', { text: '延迟校准' }),
    phaseDesc,
    !audioOk &&
      el('div', { class: 'compat-box' }, [
        el('b', { text: '替代方案：' }),
        ' 使用系统自带的音频延迟测试或耳机直连后手动填写“音频输出延迟”；本页视觉阶段仍可估计输入延迟。'
      ]),
    el('div', { class: 'card' }, [
      el('div', { class: 'form-row' }, [
        el('label', { text: '校准速度' }),
        bpmSeg
      ]),
      el('div', { class: 'btn-row' }, [startBtn, nextPhaseBtn]),
      el('p', { class: 'small muted mt', text: '操作方式：空格键 / 回车键，或点击下方方块。' })
    ]),
    el('div', { class: 'card text-center' }, [
      phaseTitle,
      progressText,
      el('div', {
        style: { display: 'flex', justifyContent: 'center', margin: '20px 0' }
      }, [flash]),
      deltaList
    ]),
    resultPanel,
    lastCalibrationCard(store)
  ]);

  page.__cleanup = () => {
    document.removeEventListener('keydown', tapHandler);
    if (runner) runner.dispose();
  };
  return page;

  function renderResult(result) {
    const saveBtn = el('button', {
      class: 'btn btn-primary',
      text: '保存校准结果并应用补偿',
      onClick: () => {
        updateStore((st) => ({
          ...st,
          calibration: result,
          settings: {
            ...st.settings,
            audioLatencyMs: result.audioLatencyMs,
            inputLatencyCompMs: Math.max(0, result.inputLatencyMs)
          }
        }));
        toast(`已应用：音频延迟 ${result.audioLatencyMs}ms，输入补偿 ${Math.max(0, result.inputLatencyMs)}ms`, 'good');
        navigate('#/calibration');
      }
    });

    const stats = [
      stat('估计输入延迟', `${result.inputLatencyMs} ms`, '敲击动作到系统感知'),
      stat('估计音频输出延迟', `${result.audioLatencyMs} ms`, result.audioSupported === false ? '音频不可用，按 0 处理' : '发声到听见的差值'),
      stat('视觉平均偏差', `${result.visual.mean} ms`, `标准差 ${result.visual.std}ms · 最快 ${result.visual.best}ms`),
      result.auditory
        ? stat('听觉平均偏差', `${result.auditory.mean} ms`, `标准差 ${result.auditory.std}ms · 最快 ${result.auditory.best}ms`)
        : stat('听觉平均偏差', '—', '浏览器不支持 Web Audio'),
      stat('校准速度', `${result.bpm} BPM`, `完成于 ${new Date(result.finishedAt).toLocaleTimeString()}`)
    ];

    resultPanel.replaceChildren(
      el('div', { class: 'card' }, [
        el('h2', { text: '校准结果' }),
        el('div', { class: 'grid grid-3' }, stats),
        el('div', { class: 'btn-row mt' }, [
          saveBtn,
          el('button', { class: 'btn', text: '去做测试', onClick: () => navigate('#/select') })
        ])
      ])
    );
  }
}

function stat(k, v, sub) {
  return el('div', { class: 'stat' }, [
    el('div', { class: 'k', text: k }),
    el('div', { class: 'v', style: { fontSize: '20px' }, text: v }),
    el('div', { class: 'sub', text: sub })
  ]);
}

function summarize(deltas) {
  const n = deltas.length || 1;
  const mean = deltas.reduce((s, d) => s + d, 0) / n;
  const variance = deltas.reduce((s, d) => s + (d - mean) ** 2, 0) / (deltas.length || 1);
  return {
    mean: Math.round(mean),
    std: Math.round(Math.sqrt(variance)),
    best: deltas.length ? Math.round(deltas.reduce((b, d) => (Math.abs(d) < Math.abs(b) ? d : b), deltas[0])) : 0
  };
}

function lastCalibrationCard(store) {
  const c = store.calibration;
  if (!c) return null;
  return el('div', { class: 'card' }, [
    el('h2', { text: '上次保存的校准' }),
    el('p', {
      class: 'small muted',
      text: `${c.bpm} BPM · 输入延迟 ${c.inputLatencyMs}ms · 音频延迟 ${c.audioLatencyMs}ms · 完成于 ${new Date(c.finishedAt).toLocaleString()}`
    })
  ]);
}

