import { describe, it, expect } from 'vitest';
import {
  generateBeats,
  generateTargets,
  generateVigilanceSchedule,
  isHitAtPoint,
  DIFFICULTY
} from '../src/core/scheduling.js';

describe('节拍生成', () => {
  it('120 BPM 间隔约 500ms 且覆盖时长', () => {
    const beats = generateBeats(120, 10000, 1, 123, 'normal');
    expect(beats.length).toBeGreaterThan(18);
    const intervals = beats.slice(1, 10).map((b, i) => b.time - beats[i].time);
    for (const iv of intervals) {
      expect(iv).toBeGreaterThan(400);
      expect(iv).toBeLessThan(600);
    }
  });
  it('细分改变拍密度', () => {
    const q = generateBeats(120, 5000, 1, 1);
    const e = generateBeats(120, 5000, 2, 1);
    expect(e.length).toBeGreaterThan(q.length);
  });
  it('相同种子结果可复现', () => {
    const a = generateBeats(100, 8000, 1, 999);
    const b = generateBeats(100, 8000, 1, 999);
    expect(a.map((x) => x.time)).toEqual(b.map((x) => x.time));
  });
  it('节拍间隔存在变化（非完全固定）', () => {
    const beats = generateBeats(120, 20000, 1, 5, 'hard');
    const intervals = beats.slice(1).map((b, i) => b.time - beats[i].time);
    expect(new Set(intervals.map((x) => Math.round(x))).size).toBeGreaterThan(1);
  });
});

describe('视觉目标生成', () => {
  const area = { width: 800, height: 500 };
  it('目标数量、位置和尺寸都在范围内', () => {
    const targets = generateTargets({ durationMs: 20000, difficulty: 'normal', seed: 3, area });
    expect(targets.length).toBeGreaterThan(5);
    for (const t of targets) {
      expect(t.x).toBeGreaterThanOrEqual(0);
      expect(t.y).toBeGreaterThanOrEqual(0);
      expect(t.x + t.size).toBeLessThanOrEqual(area.width + 2);
      expect(t.y + t.size).toBeLessThanOrEqual(area.height + 2);
      expect(t.size).toBeGreaterThanOrEqual(DIFFICULTY.normal.targetMin);
      expect(t.size).toBeLessThanOrEqual(DIFFICULTY.normal.targetMax);
    }
  });
  it('出现时间不完全固定且不早于起始延迟', () => {
    const targets = generateTargets({ durationMs: 20000, seed: 9, area });
    const gaps = targets.slice(1).map((t, i) => t.appearTime - targets[i].appearTime);
    expect(new Set(gaps).size).toBeGreaterThan(1);
    expect(targets[0].appearTime).toBeGreaterThanOrEqual(1000);
  });
  it('颜色/形状具有多样性', () => {
    const targets = generateTargets({ durationMs: 30000, seed: 11, area });
    expect(new Set(targets.map((t) => t.color)).size).toBeGreaterThan(1);
    expect(new Set(targets.map((t) => t.shape)).size).toBeGreaterThan(1);
  });
  it('可复现', () => {
    const a = generateTargets({ durationMs: 15000, seed: 42, area });
    const b = generateTargets({ durationMs: 15000, seed: 42, area });
    expect(a).toEqual(b);
  });
});

describe('持续注意调度', () => {
  it('包含需抑制的 no-go 目标且频率分段加快', () => {
    const targets = generateVigilanceSchedule({
      durationMs: 45000,
      difficulty: 'normal',
      seed: 21,
      area: { width: 800, height: 500 }
    });
    expect(targets.some((t) => t.noGo)).toBe(true);
    const phases = [0, 1, 2].map((p) => targets.filter((t) => t.phase === p));
    expect(phases[2].length).toBeGreaterThan(phases[0].length);
  });
});

describe('命中判断', () => {
  const target = { x: 100, y: 100, size: 50, shape: 'square' };
  const circle = { x: 0, y: 0, size: 40, shape: 'circle' };
  it('方形目标矩形命中区', () => {
    expect(isHitAtPoint(120, 120, target)).toBe(true);
    expect(isHitAtPoint(10, 10, target)).toBe(false);
  });
  it('圆形目标圆形命中区，角落不算命中', () => {
    expect(isHitAtPoint(20, 20, circle)).toBe(true);
    expect(isHitAtPoint(2, 2, circle)).toBe(false);
  });
});

import { describe, it, expect } from 'vitest';
import {
  createRng,
  mean,
  stdDev,
  minAbs,
  tapDeviation,
  matchTapToBeat,
  findMissedBeats,
  summarizeRhythm
} from '../src/core/time.js';

describe('随机数生成器', () => {
  it('相同种子产生相同序列', () => {
    const a = createRng(42);
    const b = createRng(42);
    const seqA = Array.from({ length: 10 }, a);
    const seqB = Array.from({ length: 10 }, b);
    expect(seqA).toEqual(seqB);
  });
  it('输出在 [0,1) 区间', () => {
    const rng = createRng(7);
    for (let i = 0; i < 1000; i += 1) {
      const v = rng();
      expect(v).toBeGreaterThanOrEqual(0);
      expect(v).toBeLessThan(1);
    }
  });
});

describe('统计工具', () => {
  it('计算均值与标准差', () => {
    expect(mean([10, 20, 30])).toBeCloseTo(20);
    expect(stdDev([10, 20, 30])).toBeCloseTo(Math.sqrt(66.6667), 2);
    expect(stdDev([5])).toBe(0);
  });
  it('minAbs 取绝对值最小的偏差', () => {
    expect(minAbs([-90, 12, -40])).toBe(12);
  });
});

describe('时间偏差', () => {
  it('晚敲为正（拖拍），早敲为负（抢拍）', () => {
    expect(tapDeviation(1050, 1000)).toBe(50);
    expect(tapDeviation(980, 1000)).toBe(-20);
  });
});

describe('敲击与节拍匹配', () => {
  const beats = [{ time: 0 }, { time: 500 }, { time: 1000 }];
  it('在窗口内匹配最近未消费节拍', () => {
    const consumed = new Set();
    const r1 = matchTapToBeat(520, beats, consumed, 80);
    expect(r1.index).toBe(1);
    expect(r1.inWindow).toBe(false); // 20ms out? actually |20| <= 80 => true
  });
  it('窗口边界判断正确', () => {
    const consumed = new Set();
    expect(matchTapToBeat(580, beats, consumed, 80).inWindow).toBe(true);
    expect(matchTapToBeat(581, beats, consumed, 80).inWindow).toBe(false);
  });
  it('已消费节拍不再匹配', () => {
    const consumed = new Set([1]);
    const r = matchTapToBeat(510, beats, consumed, 80);
    expect(r.index).not.toBe(1);
  });
  it('漏拍检测只找容差外未命中节拍', () => {
    const missed = findMissedBeats(beats, new Set([0]), 900, 80);
    expect(missed).toEqual([1]);
  });
});

describe('节奏汇总', () => {
  it('命中率、倾向与连击', () => {
    const summary = summarizeRhythm([-10, 20, 40], 1, 0, 4, [1, 2, 3]);
    expect(summary.hitRate).toBeCloseTo(0.75);
    expect(summary.maxCombo).toBe(3);
    expect(summary.tendency).toBe('steady');
  });
  it('明显拖拍判定 late', () => {
    const summary = summarizeRhythm([60, 80, 70], 0, 0, 3, [1]);
    expect(summary.tendency).toBe('late');
    expect(summary.meanAbsDelta).toBeGreaterThan(60);
  });
});

