  addRecord,
  deleteRecord,
  clearRecords,
  upsertPreset,
  deletePreset,
  recordsToCsv,
  CorruptDataError
} from '../src/core/storage.js';
import { DEFAULT_SETTINGS, sanitizeSettings } from '../src/core/settings.js';

describe('设置校验', () => {
  it('非法值回退默认', () => {
    const s = sanitizeSettings({ bpm: 'abc', volume: 5, difficulty: 'nope' });
    expect(s.bpm).toBe(DEFAULT_SETTINGS.bpm);
    expect(s.volume).toBe(1);
    expect(s.difficulty).toBe('normal');
  });
  it('数值被夹取到合法区间', () => {
    expect(sanitizeSettings({ bpm: 9999 }).bpm).toBe(300);
    expect(sanitizeSettings({ audioLatencyMs: -5 }).audioLatencyMs).toBe(0);
  });
});

describe('本地存储', () => {
  let backend;
  beforeEach(() => {
    backend = createMemoryStorage();
  });

  it('首次加载得到默认数据', () => {
    const store = loadStore(backend);
    expect(store.settings.bpm).toBe(120);
    expect(store.records).toEqual([]);
  });

  it('保存后可重新读取（模拟刷新）', () => {
    let store = loadStore(backend);
    store.settings.bpm = 167;
    store = saveStore(store, backend);
    const reloaded = loadStore(backend);
    expect(reloaded.settings.bpm).toBe(167);
  });

  it('测试记录可增删与清空，最多保留 100 条', () => {
    let store = loadStore(backend);
    const rec = (i) => ({
      id: `id-${i}`,
      type: 'reaction',
      metrics: { ok: true },
      startedAt: i
    });
    for (let i = 0; i < 105; i += 1) store = addRecord(store, rec(i));
    expect(store.records.length).toBe(100);
    expect(store.records[0].id).toBe('id-104');
    store = deleteRecord(store, 'id-104');
    expect(store.records.some((r) => r.id === 'id-104')).toBe(false);
    store = clearRecords(store);
    expect(store.records.length).toBe(0);
  });

  it('配置可新增、更新和删除', () => {
    let store = loadStore(backend);
    const p1 = { id: 'p1', name: '配置1', settings: { ...DEFAULT_SETTINGS } };
    store = saveStore(upsertPreset(store, p1), backend);
    store = upsertPreset(store, { ...p1, name: '配置1改' });
    expect(store.presets.length).toBe(1);
    expect(store.presets[0].name).toBe('配置1改');
    store = deletePreset(store, 'p1');
    expect(store.presets.length).toBe(0);
  });

  it('损坏的 JSON 抛出 CorruptDataError', () => {
    backend.setItem(STORAGE_KEY, '{not-json');
    expect(() => loadStore(backend)).toThrow(CorruptDataError);
  });

  it('结构损坏同样抛出错误，reset 后恢复默认', () => {
    backend.setItem(STORAGE_KEY, JSON.stringify('oops'));
    expect(() => loadStore(backend)).toThrow();
    const store = resetStore(backend);
    expect(store.settings.bpm).toBe(120);
  });

  it('CSV 导出包含表头并转义逗号', () => {
    let store = loadStore(backend);
    store = addRecord(store, {
      id: 'x',
      type: 'reaction',
      startedAt: Date.now(),
      finishedAt: Date.now(),
      settings: { bpm: 120, durationSec: 30, difficulty: 'normal' },
      metrics: {
        reaction: { hitRate: 0.8, avgReaction: 300, bestReaction: 220, misses: 1, falseTaps: 0 }
      },
      score: { total: 80 }
    });
    const csv = recordsToCsv(store.records);
    expect(csv.split('\n')[0]).toContain('hitRate');
    expect(csv.split('\n').length).toBe(2);
  });
});

import { describe, it, expect } from 'vitest';
import {
  speedScore,
  scoreReaction,
  scoreRhythm,
  scoreDual,
  scoreVigilance,
  summarizeReactions,
  taskSwitchLoss
} from '../src/core/scoring.js';
import { generateAdvice } from '../src/core/advice.js';

describe('速度与综合评分', () => {
  it('速度分随反应时间下降，且限制在 0-100', () => {
    expect(speedScore(200)).toBe(100);
    expect(speedScore(650)).toBe(0);
    expect(speedScore(1000)).toBe(0);
    expect(speedScore(100)).toBe(100);
  });

  it('反应测试综合分包含准确/速度/稳定', () => {
    const s = scoreReaction({
      hitRate: 0.9,
      avgReaction: 280,
      stdReaction: 60,
      falseTaps: 1,
      misses: 1
    });
    expect(s.total).toBeGreaterThan(60);
    expect(s.accuracy).toBeGreaterThan(70);
    expect(s.speed).toBeGreaterThan(70);
  });

  it('节奏分随偏差变差而降低', () => {
    const good = scoreRhythm({
      hitRate: 0.95,
      meanAbsDelta: 20,
      stdDelta: 20,
      extraTaps: 0
    });
    const bad = scoreRhythm({
      hitRate: 0.5,
      meanAbsDelta: 120,
      stdDelta: 110,
      extraTaps: 4
    });
    expect(good.total).toBeGreaterThan(bad.total);
  });

  it('双任务分被干扰惩罚', () => {
    const m = {
      rhythm: { hitRate: 0.9, meanAbsDelta: 30, stdDelta: 30, extraTaps: 0 },
      reaction: { hitRate: 0.9, avgReaction: 300, stdReaction: 60, falseTaps: 0 },
      interference: 25
    };
    const s = scoreDual(m);
    expect(s.total).toBeLessThan((s.rhythm + s.reaction) / 2);
  });

  it('疲劳分对衰退敏感', () => {
    const base = {
      firstHalf: { hitRate: 0.95, avgReaction: 280 },
      secondHalf: { hitRate: 0.95, avgReaction: 280 }
    };
    const tired = {
      firstHalf: { hitRate: 0.95, avgReaction: 280 },
      secondHalf: { hitRate: 0.7, avgReaction: 380 },
      drift: 100,
      hitDrop: 25
    };
    expect(scoreVigilance(base).stability).toBeGreaterThan(scoreVigilance(tired).stability);
  });
});

describe('反应汇总', () => {
  it('命中率、均值、最快值', () => {
    const s = summarizeReactions(
      [{ rt: 200 }, { rt: 300 }, { rt: 250 }],
      5,
      2,
      2
    );
    expect(s.avgReaction).toBeCloseTo(250);
    expect(s.bestReaction).toBe(200);
    expect(s.hitRate).toBeCloseTo(0.6);
    expect(s.falseTaps).toBe(2);
  });
});

describe('任务切换损失', () => {
  it('节拍附近的反应更慢则损失为正', () => {
    const reactions = [
      { time: 100, rt: 300 },
      { time: 200, rt: 310 },
      { time: 1000, rt: 240 },
      { time: 1100, rt: 250 }
    ];
    const loss = taskSwitchLoss(reactions, [150, 1050], 80);
    expect(loss).toBeGreaterThan(50);
  });
});

describe('数据驱动建议', () => {
  it('拖拍严重时建议上调补偿', () => {
    const tips = generateAdvice(
      {
        type: 'rhythm',
        metrics: {
          rhythm: {
            hits: 10,
            tendency: 'late',
            meanDelta: 60,
            stdDelta: 30,
            misses: 0,
            extraTaps: 0,
            totalBeats: 10,
            hitRate: 1
          }
        }
      },
      { bpm: 120 }
    );
    expect(tips.some((t) => t.includes('上调'))).toBe(true);
  });

  it('双任务下降明显时给出干扰建议', () => {
    const tips = generateAdvice({
      type: 'dual',
      metrics: {
        interference: 20,
        switchLoss: 90,
        rhythm: { hits: 5 },
        reaction: null
      }
    });
    expect(tips.some((t) => t.includes('干扰') || t.includes('切换'))).toBe(true);
  });

  it('疲劳衰退时提示休息', () => {
    const tips = generateAdvice({
      type: 'vigilance',
      metrics: {
        hitDrop: 20,
        rtDrift: 80,
        firstHalf: { falseTaps: 0 },
        secondHalf: { falseTaps: 3 }
      }
    });
    expect(tips.some((t) => t.includes('疲劳') || t.includes('休息'))).toBe(true);
  });
});

