import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { Session } from '../src/web/session.js';

class FakeAudio {
  constructor() {
    this.currentTime = 0;
    this.calls = [];
  }
  async ensureContext() {}
  async suspend() {}
  async resume() {}
  scheduleClick(when, accent) {
    this.calls.push([when, accent]);
  }
  dispose() {}
}

function makeSession(type, { beats = [], targets = [], settings } = {}) {
  const events = [];
  const session = new Session({
    type,
    settings:
      settings || {
        durationSec: 10,
        difficulty: 'normal',
        bpm: 120,
        subdivision: 1,
        audioLatencyMs: 0,
        inputLatencyCompMs: 0,
        volume: 0.5
      },
    beats,
    targets,
    audio: new FakeAudio(),
    onEvent: (e) => events.push(e)
  });
  return { session, events };
}

describe('会话：节奏命中与漏拍', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    if (!global.requestAnimationFrame) {
      global.requestAnimationFrame = (cb) => setTimeout(() => cb(performance.now()), 16);
      global.cancelAnimationFrame = (id) => clearTimeout(id);
    }
  });
  afterEach(() => vi.useRealTimers());

  it('窗口内敲击记命中，窗口外记多余敲击', async () => {
    const beats = [{ time: 500 }, { time: 1000 }, { time: 1500 }];
    const { session } = makeSession('rhythm', { beats });
    await session.start();
    vi.advanceTimersByTime(500);
    session.handleRhythmTap(performance.now());
    expect(session.rhythmHitObjs.length).toBe(1);
    vi.advanceTimersByTime(100);
    session.handleRhythmTap(performance.now());
    expect(session.extraTaps).toBe(1);
  });

  it('未在窗口内命中的节拍计为漏拍', async () => {
    const beats = [{ time: 300 }, { time: 800 }];
    const { session } = makeSession('rhythm', { beats });
    await session.start();
    vi.advanceTimersByTime(1200);
    expect(session.misses).toBeGreaterThanOrEqual(1);
  });
});

describe('会话：视觉目标', () => {
  it('点中目标记录反应时间，点空白记误触', () => {
    const targets = [
      {
        id: 0,
        appearTime: 0,
        lifetimeMs: 1000,
        x: 100,
        y: 100,
        size: 50,
        shape: 'square',
        noGo: false,
        state: 'active'
      }
    ];
    const { session } = makeSession('reaction', { targets });
    session.state = 'running';
    // 把虚拟时钟拨到目标出现后 250ms
    session.elapsedMs = 250;
    session._pausedTotal = 0;
    session._perfZero = performance.now() - session.elapsedMs;
    session.handlePointerPress(120, 120);
    expect(session.reactions[0].rt).toBe(250);
    session.handlePointerPress(5, 5);
    expect(session.falseTaps).toBe(1);
  });

  it('no-go 干扰目标被点击记抑制失败', () => {
    const targets = [
      {
        id: 0,
        appearTime: 0,
        lifetimeMs: 1000,
        x: 0,
        y: 0,
        size: 60,
        shape: 'circle',
        noGo: true,
        state: 'active'
      }
    ];
    const { session } = makeSession('vigilance', { targets });
    session.state = 'running';
    session.handlePointerPress(30, 30);
    expect(session.noGoErrorTimes.length).toBe(1);
    expect(session.falseTaps).toBe(1);
  });

  it('键盘模式命中最早出现的目标', () => {
    const targets = [
      { id: 0, appearTime: 0, lifetimeMs: 1000, x: 0, y: 0, size: 30, shape: 'square', noGo: false, state: 'active' },
      { id: 1, appearTime: 100, lifetimeMs: 1000, x: 200, y: 200, size: 30, shape: 'square', noGo: false, state: 'active' }
    ];
    const { session } = makeSession('reaction', { targets });
    session.state = 'running';
    session.elapsedMs = 300;
    session._pausedTotal = 0;
    session._perfZero = performance.now() - session.elapsedMs;
    session.handleReactionKey();
    expect(session.reactions[0].targetId).toBe(0);
  });

  it('暂停不计入虚拟时间', async () => {
    const { session } = makeSession('reaction', { targets: [] });
    await session.start();
    const t1 = session.elapsedMs;
    await session.pause();
    const before = performance.now();
    await new Promise((r) => setTimeout(r, 50));
    const wallGap = performance.now() - before;
    expect(session.state).toBe('paused');
    await session.resume();
    expect(session.elapsedMs).toBeGreaterThanOrEqual(t1);
    expect(session.elapsedMs).toBeLessThan(t1 + wallGap + 200);
  });
});

describe('会话：结果指标', () => {
  it('节奏结果包含命中率与综合分', () => {
    const { session } = makeSession('rhythm', {
      beats: [{ time: 0 }, { time: 500 }]
    });
    session.rhythmHitObjs = [{ time: 10, delta: 10 }, { time: 510, delta: 10 }];
    session.comboLog = [1, 2];
    const metrics = session._computeMetrics();
    expect(metrics.rhythm.hits).toBe(2);
    expect(metrics.score.total).toBeGreaterThan(0);
  });
});

