import { describe, it, expect } from 'vitest';
import { Session } from '../src/web/session.js';

class FakeAudio {
  constructor() {
    this.currentTime = 0;
    this.calls = [];
  }
  async ensureContext() {}
  async suspend() {}
  async resume() {}
  scheduleClick(when, accent) {
    this.calls.push([when, accent]);
  }
  dispose() {}
}

const BASE_SETTINGS = {
  durationSec: 10,
  difficulty: 'normal',
  bpm: 120,
  subdivision: 1,
  audioLatencyMs: 0,
  inputLatencyCompMs: 0,
  volume: 0.5
};

function makeSession(type, { beats = [], targets = [], settings } = {}) {
  const events = [];
  const session = new Session({
    type,
    settings: settings || BASE_SETTINGS,
    beats,
    targets,
    audio: new FakeAudio(),
    onEvent: (e) => events.push(e)
  });
  return { session, events };
}

function setVirtualTime(session, ms) {
  session.state = 'running';
  session.elapsedMs = ms;
  session._pausedTotal = 0;
  session._perfZero = performance.now() - ms;
}

function target(over = {}) {
  return {
    id: 0,
    appearTime: 0,
    lifetimeMs: 1000,
    x: 100,
    y: 100,
    size: 50,
    shape: 'square',
    noGo: false,
    state: 'waiting',
    ...over
  };
}

describe('会话：节奏命中与漏拍', () => {
  it('窗口内敲击记命中，窗口外记多余敲击', () => {
    const beats = [{ time: 500 }, { time: 1000 }, { time: 1500 }];
    const { session } = makeSession('rhythm', { beats });
    setVirtualTime(session, 500);
    session.handleRhythmTap(performance.now());
    expect(session.rhythmHitObjs.length).toBe(1);
    setVirtualTime(session, 600);
    session.handleRhythmTap(performance.now());
    expect(session.extraTaps).toBe(1);
  });

  it('输入延迟补偿把敲击有效时间前移', () => {
    const beats = [{ time: 540 }];
    const { session } = makeSession('rhythm', {
      beats,
      settings: { ...BASE_SETTINGS, inputLatencyCompMs: 40 }
    });
    setVirtualTime(session, 580);
    session.handleRhythmTap(performance.now());
    expect(session.rhythmHitObjs.length).toBe(1);
    expect(session.rhythmHitObjs[0].delta).toBe(40);
  });

  it('未在窗口内命中的节拍计为漏拍', () => {
    const beats = [{ time: 300 }, { time: 800 }];
    const { session } = makeSession('rhythm', { beats });
    session.state = 'running';
    session.elapsedMs = 1200;
    session._expireTargets();
    expect(session.misses).toBeGreaterThanOrEqual(1);
  });
});

describe('会话：视觉目标', () => {
  it('点中目标记录反应时间，点空白记误触', () => {
    const { session } = makeSession('reaction', { targets: [target()] });
    session.targets[0].state = 'active';
    setVirtualTime(session, 250);
    session.handlePointerPress(120, 120);
    expect(session.reactions[0].rt).toBe(250);
    session.handlePointerPress(5, 5);
    expect(session.falseTaps).toBe(1);
  });

  it('no-go 干扰目标被点击记抑制失败', () => {
    const { session } = makeSession('vigilance', {
      targets: [target({ x: 0, y: 0, size: 60, shape: 'circle', noGo: true })]
    });
    session.targets[0].state = 'active';
    session.state = 'running';
    session.handlePointerPress(30, 30);
    expect(session.noGoErrorTimes.length).toBe(1);
    expect(session.falseTaps).toBe(1);
  });

  it('键盘模式命中最早出现的目标', () => {
    const { session } = makeSession('reaction', {
      targets: [target({ id: 0 }), target({ id: 1, appearTime: 100, x: 200, y: 200 })]
    });
    session.targets.forEach((t) => { t.state = 'active'; });
    setVirtualTime(session, 300);
    session.handleReactionKey();
    expect(session.reactions[0].targetId).toBe(0);
  });

  it('仅存在 no-go 目标时按键算抑制失败', () => {
    const { session } = makeSession('vigilance', { targets: [target({ noGo: true })] });
    session.targets[0].state = 'active';
    session.state = 'running';
    session.handleReactionKey();
    expect(session.noGoErrorTimes.length).toBe(1);
  });

  it('暂停后虚拟时间不再前进', async () => {
    const { session } = makeSession('reaction', { targets: [] });
    session.state = 'running';
    session._perfZero = performance.now();
    await session.pause();
    expect(session.state).toBe('paused');
    const elapsedAtPause = session.elapsedMs;
    await new Promise((r) => setTimeout(r, 60));
    expect(session._virtualNow()).toBeLessThanOrEqual(elapsedAtPause + 5);
    await session.resume();
    expect(session.state).toBe('running');
    session.abort();
  });
});

describe('会话：结果指标', () => {
  it('节奏结果包含命中率与综合分', () => {
    const { session } = makeSession('rhythm', { beats: [{ time: 0 }, { time: 500 }] });
    session.rhythmHitObjs = [{ time: 10, delta: 10 }, { time: 510, delta: 10 }];
    session.comboLog = [1, 2];
    const metrics = session._computeMetrics();
    expect(metrics.rhythm.hits).toBe(2);
    expect(metrics.score.total).toBeGreaterThan(0);
  });

  it('双任务结果包含干扰与切换损失', () => {
    const { session } = makeSession('dual', {
      beats: [{ time: 100 }],
      targets: [target()]
    });
    session.rhythmHitObjs = [{ time: 100, delta: 10 }];
    session.comboLog = [1];
    session.targets[0].state = 'hit';
    session.reactions = [{ time: 150, rt: 320, nearBeat: true }];
    const metrics = session._computeMetrics();
    expect(metrics).toHaveProperty('interference');
    expect(metrics).toHaveProperty('switchLoss');
    expect(metrics.score.total).toBeGreaterThanOrEqual(0);
  });
});

