    if (this.state !== 'running') return;
    if (this.type === 'rhythm') {
      this.handleRhythmTap(perf);
      return;
    }
    const vt = this._virtualNow(perf);
    const noGoUnder = this._activeTargets().find((t) => t.noGo && pointIn(t, x, y));
    if (noGoUnder) {
      noGoUnder.state = 'failed';
      this.falseTaps += 1;
      this.falseTapTimes.push(vt);
      this.noGoErrorTimes.push(vt);
      this.onEvent({ kind: 'noGoError', target: noGoUnder });
      return;
