/**
 * 真实浏览器端到端冒烟脚本（配合系统 Chrome）。
 * 覆盖：开始页/设置持久化/两组配置/60&120 校准/四种测试/结果与建议/
 * 暂停继续/记录保存/JSON+CSV 导出/详情/双配置对比/损坏恢复。
 */
import { existsSync } from 'node:fs';
import { chromium } from 'playwright';
import { createServer } from 'vite';

const CHROME_CANDIDATES = [
  process.env.CHROME_PATH,
  'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
  'C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe',
  `${process.env.LOCALAPPDATA}\\Google\\Chrome\\Application\\chrome.exe`
].filter(Boolean);

const server = await createServer({
  server: { port: 5199, host: '127.0.0.1', open: false },
  logLevel: 'error'
});
await server.listen();
const base = 'http://127.0.0.1:5199';

const results = [];
function check(name, ok, detail = '') {
  results.push({ name, ok });
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? ' — ' + detail : ''}`);
}

async function launch() {
  const opts = {
    headless: true,
    args: ['--autoplay-policy=no-user-gesture-required']
  };
  try {
    return await chromium.launch({ ...opts, channel: 'chrome' });
  } catch {
    const exe = CHROME_CANDIDATES.find((p) => existsSync(p));
    return chromium.launch({ ...opts, executablePath: exe });
  }
}

function autoClickTargets() {
  return `(() => {
    window.__auto = setInterval(() => {
      const t = document.querySelector('.target:not(.nogo)');
      if (!t) return;
      const r = t.getBoundingClientRect();
      const target = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
      target.dispatchEvent(new PointerEvent('pointerdown', {
        bubbles: true,
        clientX: r.left + r.width / 2,
        clientY: r.top + r.height / 2
      }));
    }, 25);
  })()`;
}

function stopAuto() {
  return `clearInterval(window.__auto)`;
}

let browser;
try {
  browser = await launch();
  const context = await browser.newContext({ viewport: { width: 1366, height: 820 } });
  const page = await context.newPage();
  page.on('pageerror', (e) => console.log('PAGE ERROR:', e.message));

  await page.goto(base);
  await page.waitForSelector('text=实时节奏与反应训练系统');
  check('开始页渲染', true);

