  await page.selectOption('select', '15');
  await page.click('.seg button:has-text("鼠标")');
  await page.click('button:has-text("保存设置")');
  await page.waitForTimeout(200);
  await page.reload();
  await page.waitForTimeout(300);
  check('设置刷新后保留', (await page.inputValue('input[type=number]')) === '138');

  for (const name of ['E2E配置A', 'E2E配置B']) {
    await page.fill('#preset-name', name);
    await page.click('button:has-text("保存当前表单为配置")');
    await page.waitForTimeout(120);
  }
  check('保存两组配置', (await page.locator('.preset-item').count()) >= 2);

  // 校准
  for (const bpm of [60, 120]) {
    await page.goto(`${base}#/calibration`);
    await page.waitForTimeout(200);
    await page.click(`.seg button:has-text("${bpm} BPM")`);
    await page.click('button:has-text("开始校准")');
    const interval = 60000 / bpm;
    for (let i = 0; i < 8; i += 1) {
      await page.waitForTimeout(interval);
      await page.keyboard.press('Space');
    }
    await page.waitForTimeout(300);
    await page.click('button:has-text("进入声音阶段")');
    await page.waitForTimeout(300);
    for (let i = 0; i < 8; i += 1) {
      await page.waitForTimeout(interval);
      await page.keyboard.press('Space');
    }
    await page.waitForSelector('button:has-text("保存校准结果并应用补偿")', { timeout: 8000 });
    await page.click('button:has-text("保存校准结果并应用补偿")');
    await page.waitForTimeout(150);
    check(`校准 ${bpm} BPM 完成并保存`, true);
  }

  // 四种测试
  async function runReactionLike(type) {
    await page.goto(`${base}#/test?type=${type}`);
    await page.waitForSelector('.arena');
    await page.waitForTimeout(4000);
    await page.evaluate(autoClickTargets());
    await page.waitForTimeout(16500);
    await page.evaluate(stopAuto());
    await page.waitForSelector('h1', { timeout: 10000 });
  }

