  await page.goto(`${base}#/test?type=rhythm`);
  await page.waitForSelector('.arena');
  await page.waitForTimeout(4000);
  await page.click('button:has-text("暂停")');
  await page.waitForSelector('.pause-overlay');
  const left1 = await page.locator('.hud-kv b').first().textContent();
  await page.waitForTimeout(800);
  const left2 = await page.locator('.hud-kv b').first().textContent();
