  await page.click('button:has-text("保存本次记录")');
  await page.waitForTimeout(150);

  for (const t of ['reaction', 'dual', 'vigilance']) {
    if (t === 'dual') {
      await page.goto(`${base}#/test?type=dual`);
      await page.waitForSelector('.arena');
      await page.waitForTimeout(4000);
      await page.evaluate(`(() => {
        window.__tap = setInterval(() => document.dispatchEvent(new KeyboardEvent('keydown', { code: 'Space', bubbles: true })), 480);
      })()`);
      await page.evaluate(autoClickTargets());
      await page.waitForTimeout(16500);
      await page.evaluate(`clearInterval(window.__tap); ${stopAuto()}`);
    } else {
      await runReactionLike(t);
