    await page.click('button:has-text("保存本次记录")');
    await page.waitForTimeout(150);
    check(`${t} 记录可保存`, (await page.locator('text=已保存到历史记录').count()) >= 1);
  }

  // 记录页
  await page.goto(`${base}#/record`);
  await page.waitForTimeout(300);
  const rows = await page.locator('tbody tr').count();
  check('历史记录列表', rows >= 4, `rows=${rows}`);
  const [dl1] = await Promise.all([page.waitForEvent('download'), page.click('button:has-text("导出 JSON")')]);
  check('JSON 导出', dl1.suggestedFilename().endsWith('.json'));
  const [dl2] = await Promise.all([page.waitForEvent('download'), page.click('button:has-text("导出 CSV")')]);
  check('CSV 导出', dl2.suggestedFilename().endsWith('.csv'));
  await page.click('tbody tr:first-child button:has-text("详情")');
