    await page.waitForTimeout(16500);
    await page.evaluate(stopAuto());
    if (round === 0) {
      await page.waitForSelector('button:has-text("开始第二组")', { timeout: 8000 });
      check('对比第一组衔接第二组', true);
      await page.click('button:has-text("开始第二组")');
    }
