    await page.goto(`http://127.0.0.1:5199/${hash}`);
    await page.waitForTimeout(600);
    const app = await page.locator('#app').innerHTML();
    if (app.length < 200) errors.push(`${hash} rendered almost empty`);
    console.log('OK route', hash, 'html bytes', app.length);
  }

  // 测试页
  await page.goto('http://127.0.0.1:5199/#/test?type=reaction');
  await page.waitForSelector('.arena');
  await page.waitForTimeout(4300);
  const hasHud = await page.locator('.test-hud').count();
  console.log('test arena started, hud =', hasHud);

  if (errors.length) {
    console.log('ERRORS:\n' + errors.join('\n'));
    process.exit(1);
  }
  console.log('NO RUNTIME ERRORS');
  await browser.close();
} catch (e) {
  console.error(e);
  if (browser) await browser.close();
  process.exit(1);
}

